import{f as e,o as s,c as n,a2 as o}from"./chunks/framework.BUDOXiIz.js";const m=JSON.parse('{"title":"CoopApps — Lo esencial","description":"","frontmatter":{},"headers":[],"relativePath":"presentacion-stakeholders/lo-esencial-para-imagenes.md","filePath":"presentacion-stakeholders/lo-esencial-para-imagenes.md","lastUpdated":null}'),i={name:"presentacion-stakeholders/lo-esencial-para-imagenes.md"};function t(r,a,l,p,c,d){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="coopapps-—-lo-esencial" tabindex="-1">CoopApps — Lo esencial <a class="header-anchor" href="#coopapps-—-lo-esencial" aria-label="Permalink to &quot;CoopApps — Lo esencial&quot;">​</a></h1><p>Doce ideas, una imagen cada una. Cada idea se sostiene con un dato de la especificación o del alcance funcional; ninguna promete algo que no esté escrito.</p><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Fecha</td><td>10-11-2026</td></tr><tr><td>Fuentes</td><td><code>documento-base-presentacion.md</code> (números de la especificación y del trabajo realizado), <code>GoodApps-Cooperativas-Alcance-Funcional.md</code> (principios, límites, niveles de servicio y servicios), <code>dolores-procoop-antes-y-despues.md</code> y <code>roles-y-modulos-para-claude.md</code> (funciones del sistema actual)</td></tr><tr><td>Datos</td><td>Todos los nombres e importes de ejemplo son ficticios</td></tr></tbody></table><hr><h2 id="_0-como-usar-este-documento" tabindex="-1">0. Cómo usar este documento <a class="header-anchor" href="#_0-como-usar-este-documento" aria-label="Permalink to &quot;0. Cómo usar este documento&quot;">​</a></h2><ol><li>Puede usarse solo o después de <code>00-objetivos-alcance-y-limites-para-imagenes.md</code>, en la misma conversación.</li><li>Si la conversación es nueva, pegar primero el prompt de la sección 0.1.</li><li>Pedir las imágenes por código: &quot;Generá IMG-E01&quot;, &quot;Generá IMG-E02&quot;, etc.</li><li>Cada idea trae también una <strong>frase para decir</strong> en voz alta mientras se muestra la imagen.</li></ol><h3 id="_0-1-prompt-de-estilo-pegar-primero" tabindex="-1">0.1 Prompt de estilo (pegar primero) <a class="header-anchor" href="#_0-1-prompt-de-estilo-pegar-primero" aria-label="Permalink to &quot;0.1 Prompt de estilo (pegar primero)&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vas a dibujar doce diapositivas para una reunión con directivos y stakeholders de trayectoria, de una empresa de software para cooperativas de servicios públicos de Argentina. Cada diapositiva transmite una sola idea, con un título corto y contundente y un dato que la respalda.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>El tono es seguro y sereno: el de alguien que ya hizo el trabajo y lo muestra. Nada de adjetivos vacíos (&quot;revolucionario&quot;, &quot;increíble&quot;, &quot;disruptivo&quot;, &quot;el mejor&quot;), nada de signos de exclamación, nada de lenguaje publicitario. La fuerza está en el dato y en la frase corta, no en el adorno.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reglas obligatorias:</span></span>
<span class="line"><span>1. Usá SOLO los textos y números del documento. No inventes cifras, comparaciones ni promesas. Podés acortar sin cambiar el sentido.</span></span>
<span class="line"><span>2. Texto visible en español de Argentina.</span></span>
<span class="line"><span>3. Generá cada imagen con código (HTML con SVG en Claude; Python con matplotlib en ChatGPT), 1920×1080 px. No uses el generador de imágenes para nada que tenga texto.</span></span>
<span class="line"><span>4. Paleta: gris carbón #2F343A, gris medio #6B7280, gris claro #E5E7EB, blanco #FFFFFF y verde cooperativo #2E7D32 como único acento. Ámbar #B7791F solo donde el documento lo indique. Sin rojo.</span></span>
<span class="line"><span>5. Composición de alto impacto: mucho espacio en blanco, un título grande (64 a 80 px), un número o un contraste dominante y como máximo tres elementos de apoyo. Texto mínimo de 20 px.</span></span>
<span class="line"><span>6. Tipografía sans serif limpia (Inter o similar), con peso fuerte en títulos y cifras.</span></span>
<span class="line"><span>7. Íconos de línea simples. Nada de robots, cerebros, cohetes, personas sonriendo ni efectos futuristas.</span></span>
<span class="line"><span>8. Datos de ejemplo siempre ficticios (&quot;Cooperativa A&quot;, &quot;Socio de ejemplo&quot;, &quot;ARS 0.000&quot;).</span></span>
<span class="line"><span>9. Después de cada imagen, listá qué datos del documento usaste.</span></span>
<span class="line"><span>Esperá mi pedido por código (IMG-E01 a IMG-E12).</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><hr><h2 id="_1-las-doce-ideas" tabindex="-1">1. Las doce ideas <a class="header-anchor" href="#_1-las-doce-ideas" aria-label="Permalink to &quot;1. Las doce ideas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Código</th><th>Título de la imagen</th><th>Idea que deja</th></tr></thead><tbody><tr><td>IMG-E01</td><td>Seis meses. Seis días.</td><td>El análisis ya está hecho</td></tr><tr><td>IMG-E02</td><td>Está todo escrito.</td><td>Nada queda librado a la interpretación</td></tr><tr><td>IMG-E03</td><td>Cada requisito tiene su prueba.</td><td>Lo escrito se puede verificar</td></tr><tr><td>IMG-E04</td><td>Nada de lo que hoy funciona se pierde.</td><td>La transición no le quita nada a la cooperativa</td></tr><tr><td>IMG-E05</td><td>Cada peso, explicado.</td><td>La factura se defiende sola</td></tr><tr><td>IMG-E06</td><td>Nada se borra.</td><td>Control y auditoría totales</td></tr><tr><td>IMG-E07</td><td>La ley no se configura.</td><td>Las protecciones normativas son fijas</td></tr><tr><td>IMG-E08</td><td>Si ARCA se cae, la cooperativa sigue.</td><td>Continuidad</td></tr><tr><td>IMG-E09</td><td>La cooperativa, en el bolsillo del socio.</td><td>Experiencia digital con marca propia</td></tr><tr><td>IMG-E10</td><td>Sin servidores. Sin instalaciones. Sin copias a mano.</td><td>Menos carga operativa</td></tr><tr><td>IMG-E11</td><td>Los datos son de la cooperativa.</td><td>Libertad y control de su información</td></tr><tr><td>IMG-E12</td><td>Primero medimos. Después prometemos.</td><td>Riesgo controlado; el plazo se calibra con datos</td></tr></tbody></table><p>Cierre opcional: <strong>IMG-E13 — Lo que falta lo aportan ustedes.</strong></p><hr><h2 id="_2-fichas-y-prompts" tabindex="-1">2. Fichas y prompts <a class="header-anchor" href="#_2-fichas-y-prompts" aria-label="Permalink to &quot;2. Fichas y prompts&quot;">​</a></h2><h3 id="img-e01-—-seis-meses-seis-dias" tabindex="-1">IMG-E01 — Seis meses. Seis días. <a class="header-anchor" href="#img-e01-—-seis-meses-seis-dias" aria-label="Permalink to &quot;IMG-E01 — Seis meses. Seis días.&quot;">​</a></h3><p><strong>Respaldo:</strong> el plan tradicional preveía 6 meses (26 semanas) para relevar, analizar y especificar. El trabajo se hizo en unos 6 días de trabajo efectivo, en noviembre de 2026: unas 25 veces más rápido.</p><p><strong>Frase para decir:</strong> &quot;Lo que estaba planificado para seis meses ya está hecho. Ahora lo que necesitamos es su mirada.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-E01 con código.</span></span>
<span class="line"><span>Título grande: &quot;Seis meses. Seis días.&quot;</span></span>
<span class="line"><span>Composición: dos barras horizontales enormes, una sobre otra, en escala real de semanas (0 a 26).</span></span>
<span class="line"><span>- Barra 1, gris medio, a todo el ancho: &quot;Plan tradicional: relevar, analizar y especificar&quot; y, al final, &quot;6 meses&quot;.</span></span>
<span class="line"><span>- Barra 2, verde, de 1/26 del ancho: &quot;Trabajo realizado&quot; y, al final, &quot;6 días&quot;.</span></span>
<span class="line"><span>El contraste de largo es el mensaje: no agregues más elementos.</span></span>
<span class="line"><span>Pie pequeño: &quot;Relevamiento, análisis y especificación completos · noviembre de 2026&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="img-e02-—-esta-todo-escrito" tabindex="-1">IMG-E02 — Está todo escrito. <a class="header-anchor" href="#img-e02-—-esta-todo-escrito" aria-label="Permalink to &quot;IMG-E02 — Está todo escrito.&quot;">​</a></h3><p><strong>Respaldo:</strong> la especificación tiene:</p><ul><li>más de 4.200 requisitos funcionales y 292 no funcionales;</li><li>unas 2.680 reglas de negocio y unos 2.490 parámetros con nombre;</li><li>1.051 pantallas y 558 ítems de menú;</li><li>4.193 operaciones de API;</li><li>115 integraciones;</li><li>471 casos de uso y 341 procesos;</li><li>5.710 casos de prueba;</li><li>31 anexos.</li></ul><p><strong>Frase para decir:</strong> &quot;No hay que imaginarse el sistema: está escrito, pantalla por pantalla y regla por regla.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-E02 con código.</span></span>
<span class="line"><span>Título grande: &quot;Está todo escrito.&quot;</span></span>
<span class="line"><span>Subtítulo: &quot;Pantalla por pantalla. Regla por regla. Prueba por prueba.&quot;</span></span>
<span class="line"><span>Composición: una cuadrícula de 4 × 2 cifras grandes en verde, con su rótulo debajo en gris:</span></span>
<span class="line"><span>&quot;+4.200&quot; requisitos funcionales · &quot;2.680&quot; reglas de negocio · &quot;2.490&quot; parámetros con nombre · &quot;1.051&quot; pantallas · &quot;4.193&quot; operaciones de API · &quot;115&quot; integraciones · &quot;471&quot; casos de uso · &quot;5.710&quot; casos de prueba.</span></span>
<span class="line"><span>Debajo, una línea fina gris: &quot;292 requisitos no funcionales · 558 ítems de menú · 341 procesos · 31 anexos&quot;.</span></span>
<span class="line"><span>Las cifras tienen que dominar la imagen; nada de gráficos.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="img-e03-—-cada-requisito-tiene-su-prueba" tabindex="-1">IMG-E03 — Cada requisito tiene su prueba. <a class="header-anchor" href="#img-e03-—-cada-requisito-tiene-su-prueba" aria-label="Permalink to &quot;IMG-E03 — Cada requisito tiene su prueba.&quot;">​</a></h3><p><strong>Respaldo:</strong> el 100 % de los requisitos tiene trazabilidad a casos de uso y a casos de prueba; las 1.051 pantallas y las 4.193 operaciones de API están cubiertas al 100 %. Hay 5.710 casos de prueba de aceptación y 196 casos de aceptación de negocio, con criterios de salida por ola.</p><p><strong>Frase para decir:</strong> &quot;Cada cosa que prometemos tiene una prueba escrita que dice cómo comprobarla.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-E03 con código.</span></span>
<span class="line"><span>Título grande: &quot;Cada requisito tiene su prueba.&quot;</span></span>
<span class="line"><span>Composición: una cadena horizontal de cuatro eslabones unidos, de izquierda a derecha: &quot;Requisito&quot; → &quot;Caso de uso&quot; → &quot;Pantalla y API&quot; → &quot;Caso de prueba&quot;. Debajo de cada eslabón, su cifra: &quot;+4.200&quot;, &quot;471&quot;, &quot;1.051 · 4.193&quot;, &quot;5.710&quot;.</span></span>
<span class="line"><span>A la derecha, un sello circular verde grande: &quot;100 % trazado&quot;.</span></span>
<span class="line"><span>Pie: &quot;196 casos de aceptación de negocio · Criterios de salida en cada ola&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="img-e04-—-nada-de-lo-que-hoy-funciona-se-pierde" tabindex="-1">IMG-E04 — Nada de lo que hoy funciona se pierde. <a class="header-anchor" href="#img-e04-—-nada-de-lo-que-hoy-funciona-se-pierde" aria-label="Permalink to &quot;IMG-E04 — Nada de lo que hoy funciona se pierde.&quot;">​</a></h3><p><strong>Respaldo:</strong> de las 120 funciones del menú del sistema actual, 112 se absorben en un módulo, 7 se reemplazan por una solución mejor y 1 se descarta. Los 1.536 parámetros numéricos del sistema actual están catalogados y pasan a ser parámetros con nombre. El alcance incluye todas las funciones, también las menos frecuentes.</p><p><strong>Frase para decir:</strong> &quot;Revisamos función por función lo que la cooperativa usa hoy. Ninguna se queda sin destino.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-E04 con código.</span></span>
<span class="line"><span>Título grande: &quot;Nada de lo que hoy funciona se pierde.&quot;</span></span>
<span class="line"><span>Composición: a la izquierda, un número enorme &quot;120&quot; con el rótulo &quot;funciones del sistema actual&quot;. A la derecha, tres bloques apilados con su cifra grande:</span></span>
<span class="line"><span>- verde: &quot;112 · se conservan en su módulo&quot;;</span></span>
<span class="line"><span>- verde más claro: &quot;7 · se reemplazan por algo mejor&quot;;</span></span>
<span class="line"><span>- gris: &quot;1 · se descarta&quot;.</span></span>
<span class="line"><span>Debajo, una banda gris claro: &quot;1.536 parámetros numéricos catalogados → parámetros con nombre, explicación y vigencia&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="img-e05-—-cada-peso-explicado" tabindex="-1">IMG-E05 — Cada peso, explicado. <a class="header-anchor" href="#img-e05-—-cada-peso-explicado" aria-label="Permalink to &quot;IMG-E05 — Cada peso, explicado.&quot;">​</a></h3><p><strong>Respaldo:</strong> cada factura muestra por qué se cobró cada renglón y qué configuración se aplicó, con su versión. La facturación tiene controles previos y cero diferencias entre factura, cuenta corriente y contabilidad.</p><p><strong>Frase para decir:</strong> &quot;Cuando un socio pregunta por qué pagó lo que pagó, la respuesta está en la misma factura.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-E05 con código.</span></span>
<span class="line"><span>Título grande: &quot;Cada peso, explicado.&quot;</span></span>
<span class="line"><span>Composición: a la izquierda, una factura ficticia limpia de &quot;Cooperativa A&quot; con cuatro renglones (por ejemplo: &quot;Abono Internet ARS 0.000&quot;, &quot;Proporcional desde la activación ARS 0.000&quot;, &quot;Instalación ARS 0.000&quot;, &quot;Cuota social ARS 0.000&quot;). Del segundo renglón sale una línea fina hacia la derecha, a una tarjeta &quot;Por qué se cobró&quot;: &quot;Activación efectiva: día 12 · Plan de ejemplo, versión 3 · Regla: proporcional por días&quot;.</span></span>
<span class="line"><span>Abajo, tres tildes verdes: &quot;Controles antes de emitir&quot; · &quot;Cero diferencias entre factura, cuenta corriente y contabilidad&quot; · &quot;Configuración registrada con su versión&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="img-e06-—-nada-se-borra" tabindex="-1">IMG-E06 — Nada se borra. <a class="header-anchor" href="#img-e06-—-nada-se-borra" aria-label="Permalink to &quot;IMG-E06 — Nada se borra.&quot;">​</a></h3><p><strong>Respaldo:</strong> los documentos económicos nunca se borran: se anulan o se revierten. Cada operación registra autor, fecha y motivo, en una auditoría inmutable. Apagar un módulo o un servicio no borra la historia: la deja en solo consulta.</p><p><strong>Frase para decir:</strong> &quot;En este sistema siempre se puede saber quién hizo qué, cuándo y por qué.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-E06 con código.</span></span>
<span class="line"><span>Título grande: &quot;Nada se borra.&quot;</span></span>
<span class="line"><span>Subtítulo: &quot;Se anula, se revierte, se deja constancia.&quot;</span></span>
<span class="line"><span>Composición: una línea de tiempo vertical sobria con cuatro registros ficticios, cada uno con &quot;quién · cuándo · qué · por qué&quot; (por ejemplo: &quot;Usuario de ejemplo · 10/11 09:14 · Anuló la factura 0001-00000000 · Motivo: error de domicilio&quot;; &quot;Usuario de ejemplo · 10/11 09:16 · Emitió nota de crédito&quot;; etc.).</span></span>
<span class="line"><span>A la derecha, tres afirmaciones grandes con tilde verde: &quot;Autor, fecha y motivo en cada operación&quot; · &quot;Auditoría que no se puede alterar&quot; · &quot;Apagar un servicio no borra su historia&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="img-e07-—-la-ley-no-se-configura" tabindex="-1">IMG-E07 — La ley no se configura. <a class="header-anchor" href="#img-e07-—-la-ley-no-se-configura" aria-label="Permalink to &quot;IMG-E07 — La ley no se configura.&quot;">​</a></h3><p><strong>Respaldo:</strong> las protecciones por condición, los preavisos y las ventanas que fija la norma no pueden ser modificados por la cooperativa. Algunos ejemplos:</p><ul><li>nunca se corta la electricidad a un electrodependiente acreditado;</li><li>el agua respeta un caudal mínimo vital;</li><li>en telefonía, las llamadas de emergencia siempre funcionan;</li><li>una prestación urgente de sepelio o salud nunca se rechaza por deuda;</li><li>el cementerio nunca dispone de restos por falta de pago;</li><li>la baja de Internet, telefonía y televisión es pública y sin cargo.</li></ul><p><strong>Frase para decir:</strong> &quot;Hay cosas que el sistema no deja hacer, aunque alguien quiera. Eso protege al socio y protege a la cooperativa.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-E07 con código.</span></span>
<span class="line"><span>Título grande: &quot;La ley no se configura.&quot;</span></span>
<span class="line"><span>Subtítulo: &quot;Las protecciones que fija la norma están en el sistema y nadie las puede desactivar.&quot;</span></span>
<span class="line"><span>Composición: seis tarjetas iguales en cuadrícula de 3 × 2, con borde ámbar e ícono de escudo:</span></span>
<span class="line"><span>&quot;Nunca se corta a un electrodependiente&quot; · &quot;El agua respeta el caudal mínimo vital&quot; · &quot;Las llamadas de emergencia siempre funcionan&quot; · &quot;Una urgencia nunca se rechaza por deuda&quot; · &quot;Nunca se dispone de restos por falta de pago&quot; · &quot;La baja de Internet, telefonía y TV es pública y sin cargo&quot;.</span></span>
<span class="line"><span>Pie: &quot;Protege al socio. Protege a la cooperativa.&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="img-e08-—-si-arca-se-cae-la-cooperativa-sigue" tabindex="-1">IMG-E08 — Si ARCA se cae, la cooperativa sigue. <a class="header-anchor" href="#img-e08-—-si-arca-se-cae-la-cooperativa-sigue" aria-label="Permalink to &quot;IMG-E08 — Si ARCA se cae, la cooperativa sigue.&quot;">​</a></h3><p><strong>Respaldo:</strong> una caída del organismo fiscal, de un banco o de una pasarela no detiene la atención ni la facturación: la operación queda pendiente y se completa al volver el servicio. Los procesos masivos se pausan y se reanudan sin duplicar facturas ni pagos. Disponibilidad del 99,5 % mensual, pérdida máxima de datos de 15 minutos y recuperación de una cooperativa en 4 horas.</p><p><strong>Frase para decir:</strong> &quot;Los proveedores externos van a fallar alguna vez. La cooperativa no se detiene por eso.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-E08 con código.</span></span>
<span class="line"><span>Título grande: &quot;Si ARCA se cae, la cooperativa sigue.&quot;</span></span>
<span class="line"><span>Composición: en el centro, un bloque verde &quot;Cooperativa A: atiende, factura, cobra&quot;. Alrededor, cuatro proveedores en gris (ARCA, Banco, Pasarela de pagos, Mensajería); uno de ellos con un ícono de desconexión y la etiqueta &quot;sin respuesta → queda pendiente y se completa al volver&quot;.</span></span>
<span class="line"><span>Abajo, una franja con tres cifras grandes: &quot;99,5 % disponibilidad&quot; · &quot;15 min pérdida máxima de datos&quot; · &quot;4 h para recuperar una cooperativa&quot;.</span></span>
<span class="line"><span>Pie: &quot;Los procesos masivos se pausan y se retoman sin duplicar facturas ni pagos&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="img-e09-—-la-cooperativa-en-el-bolsillo-del-socio" tabindex="-1">IMG-E09 — La cooperativa, en el bolsillo del socio. <a class="header-anchor" href="#img-e09-—-la-cooperativa-en-el-bolsillo-del-socio" aria-label="Permalink to &quot;IMG-E09 — La cooperativa, en el bolsillo del socio.&quot;">​</a></h3><p><strong>Respaldo:</strong> la aplicación del socio se instala con el nombre, el ícono y los colores de cada cooperativa. Desde ahí el socio contrata, elige el turno de la visita, ve al técnico &quot;en camino&quot;, consulta consumos y facturas, paga, reclama con fotos, firma y da de baja. Está pensada para celulares de gama baja y conexión lenta.</p><p><strong>Frase para decir:</strong> &quot;El socio ya no tiene que ir a la oficina. Y lo que ve es su cooperativa, no un sistema ajeno.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-E09 con código.</span></span>
<span class="line"><span>Título grande: &quot;La cooperativa, en el bolsillo del socio.&quot;</span></span>
<span class="line"><span>Composición: tres celulares en fila, del mismo tamaño, cada uno con la marca de una cooperativa ficticia distinta (Cooperativa A en verde, Cooperativa B en azul petróleo, Cooperativa C en bordó suave), con la misma pantalla de inicio: saldo &quot;ARS 0.000&quot;, próximo vencimiento, botón central &quot;Pagar&quot; y barra inferior (Inicio, Cuentas y servicios, +, Gestiones, Comunidad).</span></span>
<span class="line"><span>Debajo, una fila de siete íconos con rótulo: Contratar · Elegir turno · Técnico en camino · Consumos · Pagar · Reclamar con fotos · Dar de baja.</span></span>
<span class="line"><span>Pie: &quot;Una plataforma. La marca de cada cooperativa.&quot;</span></span>
<span class="line"><span>Excepción a la paleta: solo los colores de marca de los tres celulares pueden salir del verde.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="img-e10-—-sin-servidores-sin-instalaciones-sin-copias-a-mano" tabindex="-1">IMG-E10 — Sin servidores. Sin instalaciones. Sin copias a mano. <a class="header-anchor" href="#img-e10-—-sin-servidores-sin-instalaciones-sin-copias-a-mano" aria-label="Permalink to &quot;IMG-E10 — Sin servidores. Sin instalaciones. Sin copias a mano.&quot;">​</a></h3><p><strong>Respaldo:</strong> se usa desde el navegador y el celular, sin instalar programas, sin administrar servidores y sin hacer copias de seguridad manuales. Todas las cooperativas tienen la misma versión, siempre actualizada y sin cortes. El alta de una cooperativa lleva un día hábil como máximo, sin programadores.</p><p><strong>Frase para decir:</strong> &quot;La cooperativa deja de ocuparse de la informática y se ocupa de sus socios.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-E10 con código.</span></span>
<span class="line"><span>Título grande en tres líneas: &quot;Sin servidores. / Sin instalaciones. / Sin copias a mano.&quot;</span></span>
<span class="line"><span>Composición: a la izquierda el título; a la derecha, una columna de cuatro afirmaciones grandes con tilde verde:</span></span>
<span class="line"><span>&quot;Desde el navegador y el celular&quot; · &quot;Misma versión para todas, siempre actualizada&quot; · &quot;Copias de seguridad automáticas&quot; · &quot;Una cooperativa nueva en un día hábil, sin programadores&quot;.</span></span>
<span class="line"><span>Pie: &quot;La cooperativa se ocupa de sus socios, no de la informática.&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="img-e11-—-los-datos-son-de-la-cooperativa" tabindex="-1">IMG-E11 — Los datos son de la cooperativa. <a class="header-anchor" href="#img-e11-—-los-datos-son-de-la-cooperativa" aria-label="Permalink to &quot;IMG-E11 — Los datos son de la cooperativa.&quot;">​</a></h3><p><strong>Respaldo:</strong> la cooperativa puede consultar, exportar e integrar sus datos siempre, mediante reportes, tableros e interfaz de integración con credenciales propias. Si deja el servicio, recibe la exportación completa en formatos abiertos, con control de integridad, y un período de solo consulta. CoopApps trata los datos personales por cuenta de la cooperativa: no los usa para otros fines ni los cede.</p><p><strong>Frase para decir:</strong> &quot;La información de los socios es de la cooperativa. Hoy y el día que decida irse.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-E11 con código.</span></span>
<span class="line"><span>Título grande: &quot;Los datos son de la cooperativa.&quot;</span></span>
<span class="line"><span>Subtítulo: &quot;Hoy, mañana y el día que decida irse.&quot;</span></span>
<span class="line"><span>Composición: en el centro, un ícono de llave grande en verde sobre un bloque &quot;Datos de la Cooperativa A&quot;. De él salen tres caminos con rótulo: &quot;Reportes y tableros&quot; · &quot;Integración con sus propios sistemas&quot; · &quot;Exportación completa en formatos abiertos&quot;.</span></span>
<span class="line"><span>Abajo, una banda gris claro: &quot;CoopApps trata los datos por cuenta de la cooperativa: no los usa para otros fines ni los cede&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="img-e12-—-primero-medimos-despues-prometemos" tabindex="-1">IMG-E12 — Primero medimos. Después prometemos. <a class="header-anchor" href="#img-e12-—-primero-medimos-despues-prometemos" aria-label="Permalink to &quot;IMG-E12 — Primero medimos. Después prometemos.&quot;">​</a></h3><p><strong>Respaldo:</strong> la estimación conservadora de la construcción da 17.504 puntos de complejidad, con un supuesto de 2 horas por punto que hay que calibrar. La propuesta es construir las primeras instrucciones de la ola O0 durante 2 o 3 semanas, medir las horas reales por punto y volver con una fecha basada en datos. Cada etapa entrega un resultado visible que la cooperativa piloto valida.</p><p><strong>Frase para decir:</strong> &quot;No vamos a darles una fecha inventada. En tres semanas les traemos una fecha medida.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-E12 con código.</span></span>
<span class="line"><span>Título grande: &quot;Primero medimos. Después prometemos.&quot;</span></span>
<span class="line"><span>Composición: tres pasos grandes en fila, unidos por flechas cortas:</span></span>
<span class="line"><span>1. &quot;Construir&quot; — &quot;Las primeras instrucciones de la ola O0, durante 2 o 3 semanas&quot;.</span></span>
<span class="line"><span>2. &quot;Medir&quot; — &quot;Horas reales por punto: cada instrucción ya tiene su puntaje&quot;.</span></span>
<span class="line"><span>3. &quot;Comprometer&quot; — &quot;Una fecha basada en datos, no en supuestos&quot;.</span></span>
<span class="line"><span>Debajo, una línea fina con &quot;17.504 puntos de complejidad ya calculados · 172 instrucciones · 12 olas&quot;.</span></span>
<span class="line"><span>Pie: &quot;Cada etapa entrega un resultado visible que valida la cooperativa piloto&quot;.</span></span>
<span class="line"><span>No muestres ninguna cifra de semanas ni de meses de construcción.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="img-e13-—-lo-que-falta-lo-aportan-ustedes-cierre-opcional" tabindex="-1">IMG-E13 — Lo que falta lo aportan ustedes (cierre opcional) <a class="header-anchor" href="#img-e13-—-lo-que-falta-lo-aportan-ustedes-cierre-opcional" aria-label="Permalink to &quot;IMG-E13 — Lo que falta lo aportan ustedes (cierre opcional)&quot;">​</a></h3><p><strong>Respaldo:</strong> el relevamiento, el análisis y la especificación ya están hechos. Lo que falta es lo que solo puede aportar quien conoce el negocio: validar, decidir y priorizar.</p><p><strong>Frase para decir:</strong> &quot;El trabajo pesado está hecho. Lo que necesitamos ahora es lo que solo ustedes saben.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-E13 con código.</span></span>
<span class="line"><span>Título grande: &quot;Lo que falta lo aportan ustedes.&quot;</span></span>
<span class="line"><span>Composición: a la izquierda, una columna gris con tres tildes: &quot;Relevado&quot; · &quot;Analizado&quot; · &quot;Especificado&quot;.</span></span>
<span class="line"><span>A la derecha, una columna verde, más grande, con tres verbos: &quot;Validar&quot; · &quot;Decidir&quot; · &quot;Priorizar&quot;.</span></span>
<span class="line"><span>Entre ambas, una línea vertical fina.</span></span>
<span class="line"><span>Pie: &quot;Su experiencia es la pieza que completa el trabajo.&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="_3-notas-para-el-presentador" tabindex="-1">3. Notas para el presentador <a class="header-anchor" href="#_3-notas-para-el-presentador" aria-label="Permalink to &quot;3. Notas para el presentador&quot;">​</a></h2><ul><li><strong>Orden sugerido para abrir con fuerza:</strong> E01, E02 y E04. Para cerrar: E12 y E13.</li><li><strong>Si solo hay lugar para cinco:</strong> E01, E02, E04, E07 y E12.</li><li><strong>La frase para decir va con la imagen, no en la imagen.</strong> La diapositiva queda limpia y el presentador pone la voz.</li><li><strong>Requisitos funcionales.</strong> El documento base dice 4.204 y el cálculo más reciente da 4.213; por eso las imágenes dicen &quot;más de 4.200&quot;, que es cierto con cualquiera de los dos.</li><li><strong>E12 no debe mostrar las 314 semanas</strong> de la estimación sin calibrar; el mensaje es que el plazo se mide antes de comprometerlo.</li><li><strong>No nombrar al sistema actual ni a sus autores en las imágenes.</strong> Las comparaciones dicen &quot;el sistema actual&quot;, para que nadie en la sala se sienta atacado.</li></ul>`,71)])])}const b=e(i,[["render",t]]);export{m as __pageData,b as default};
